\title{Root Incidences, Permutation Fixed Points, and the\\Finite-Field Correction to Stochastic Galois Theory}
\author{Aristotle}
\date{18 July 2026}

\begin{document}
\maketitle

\begin{abstract}
A tempting finite-field analogue of generic Galois-group phenomena asserts that a random degree-$n$ polynomial over $\F_q$ should have Galois group $S_n$ with probability tending to one. Literally interpreted, this is false for $n\ge3$: finite-field Galois groups are cyclic, whereas $S_n$ is noncommutative. The appropriate correspondence concerns Frobenius cycle type, equivalently irreducible-factor degrees. We prove its exact first-moment case in a form valid over every finite commutative ring. If $K$ has $q$ elements and $n>0$, the sum of root counts over all $q^n$ monic degree-$n$ polynomials is $q^n$. Independently, the sum of fixed-point counts over $S_n$ is $n!$. Thus both uniform models have expectation exactly one. We give double-counting proofs, explain the cyclicity obstruction, describe exhaustive algorithms, and place the result within the Frobenius factorization dictionary.
\end{abstract}

\section{Introduction}
A separable polynomial of degree $n$ has $n$ geometric roots, and field automorphisms permute them. Over global fields, large symmetric Galois groups are common. A direct transplant of this principle to finite fields, however, encounters a structural obstruction: every finite extension of a finite field has cyclic automorphism group, generated by Frobenius. Since $S_n$ is noncommutative for $n\ge3$, increasing the base-field size cannot make such a group symmetric.

The surviving permutation model is both precise and useful. If $f\in\F_q[X]$ is squarefree, the map $x\mapsto x^q$ permutes its geometric roots. An irreducible factor of degree $d$ contributes one orbit, hence one cycle, of length $d$. Factorization type is therefore Frobenius cycle type. In particular, roots in $\F_q$ correspond to fixed points.

We isolate this first statistic. For a finite commutative ring $K$, write every monic degree-$n$ polynomial uniquely as
\[
f_v(X)=X^n+\sum_{i=0}^{n-1}v_iX^i,\qquad v\in K^n.
\]
We prove that its average number of roots in $K$ is one. The parallel average number of fixed points in $S_n$ is also one. Both are exact finite identities, not asymptotic statements.

\section{Definitions and incidence spaces}
\begin{definition}[Root statistic]
Let $K$ be a finite commutative ring of cardinality $q$ and let $n>0$. For $v\in K^n$, define
\[
R(v)=\#\{r\in K:f_v(r)=0\}.
\]
Roots are counted as distinct elements of $K$, without multiplicity.
\end{definition}

\begin{definition}[Fixed-point statistic]
For $\sigma\in S_n$, define
\[
F(\sigma)=\#\{i\in\{1,\ldots,n\}:\sigma(i)=i\}.
\]
\end{definition}

Introduce the incidence sets
\[
\mathcal I_{K,n}=\{(v,r)\in K^n\times K:f_v(r)=0\},
\qquad
\mathcal J_n=\{(\sigma,i)\in S_n\times\{1,\ldots,n\}:\sigma(i)=i\}.
\]
Counting each set in two orders proves the main identities.

\section{Polynomial root incidences}
\begin{lemma}[Prescribed-root fiber]\label{lem:fiber}
Let $K$ be a finite commutative ring with $q$ elements, let $m\ge0$, and fix $r\in K$. Exactly $q^m$ monic polynomials of degree $m+1$ vanish at $r$.
\end{lemma}
\begin{proof}
Write
\[
f(X)=X^{m+1}+v_mX^m+\cdots+v_1X+v_0.
\]
The equation $f(r)=0$ is equivalent to
\[
v_0=-\left(r^{m+1}+\sum_{j=1}^{m}v_jr^j\right).
\]
The $m$ coefficients $v_1,\ldots,v_m$ are arbitrary, after which $v_0$ is uniquely forced. Thus the fiber is in bijection with $K^m$ and has size $q^m$. No division is used, so zero divisors cause no difficulty.
\end{proof}

\begin{theorem}[Exact Root-Incidence Theorem]\label{thm:roots}
For every finite commutative ring $K$ of cardinality $q$ and every $n>0$,
\[
\sum_{v\in K^n}R(v)=q^n.
\]
Consequently, a uniformly selected monic degree-$n$ polynomial has $\E[R]=1$.
\end{theorem}
\begin{proof}
Count $\mathcal I_{K,n}$. Counting first by $v$ gives $\sum_vR(v)$. Write $n=m+1$. For each of the $q$ choices of $r$, Lemma~\ref{lem:fiber} gives $q^m=q^{n-1}$ polynomials vanishing at $r$. Hence
\[
\card{\mathcal I_{K,n}}=q\,q^{n-1}=q^n.
\]
There are $q^n$ coefficient vectors, so normalization gives expectation one.
\end{proof}

\begin{corollary}[Uniform root probability]
For a fixed $r\in K$ and uniform $v\in K^n$,
\[
\Prob(f_v(r)=0)=\frac1q.
\]
\end{corollary}
\begin{proof}
The relevant fiber has $q^{n-1}$ elements out of $q^n$ coefficient vectors.
\end{proof}

Equivalently, if $I_r(v)$ is the indicator of $f_v(r)=0$, then $R(v)=\sum_r I_r(v)$. Linearity of expectation gives
\[
\E[R]=\sum_{r\in K}\E[I_r]=q\cdot\frac1q=1,
\]
without any independence assumption.

\section{Permutation fixed-point incidences}
\begin{lemma}[Stabilizer count]\label{lem:stab}
For $n>0$ and a fixed letter $i$, exactly $(n-1)!$ permutations in $S_n$ fix $i$.
\end{lemma}
\begin{proof}
Once $i$ is fixed, the other $n-1$ letters may be permuted arbitrarily. Equivalently, orbit--stabilizer gives $n\card{\operatorname{Stab}(i)}=n!$.
\end{proof}

\begin{theorem}[Exact Fixed-Point-Incidence Theorem]\label{thm:fixed}
For every $n>0$,
\[
\sum_{\sigma\in S_n}F(\sigma)=n!.
\]
Consequently, a uniform permutation has $\E[F]=1$.
\end{theorem}
\begin{proof}
Count $\mathcal J_n$ by first fixing the letter. Lemma~\ref{lem:stab} gives
\[
\card{\mathcal J_n}=n(n-1)!=n!.
\]
Counting first by $\sigma$ gives $\sum_\sigma F(\sigma)$. Normalization by $n!$ completes the proof.
\end{proof}

\section{The exact bridge}
\begin{theorem}[Root--Fixed-Point Bridge]\label{thm:bridge}
Let $K$ be a finite commutative ring with $q$ elements and let $n>0$. Then
\[
\left(\sum_{v\in K^n}R(v)\right)n!
=
\left(\sum_{\sigma\in S_n}F(\sigma)\right)q^n.
\]
Equivalently,
\[
\E_{v\in K^n}[R(v)]=\E_{\sigma\in S_n}[F(\sigma)]=1.
\]
\end{theorem}
\begin{proof}
By Theorems~\ref{thm:roots} and~\ref{thm:fixed}, both sides equal $q^n n!$.
\end{proof}

This is an equality of normalized incidence densities, not a bijection between individual polynomials and permutations and not an equality of full distributions. The parallel fiber structures are nevertheless exact: prescribing a root leaves $n-1$ free coefficients, while prescribing a fixed point leaves $n-1$ letters to permute.

\section{The finite-field correction}
\begin{lemma}[Noncommutativity of $S_n$]
For every $n\ge3$, the symmetric group $S_n$ is noncommutative.
\end{lemma}
\begin{proof}
On three selected letters, the transposition of the first two and the transposition of the last two do not commute, as evaluation on the first letter shows.
\end{proof}

\begin{theorem}[Finite-Field Cyclicity Obstruction]\label{thm:obstruction}
Let $L/K$ be a finite extension of finite fields. For every $n\ge3$, the group of $K$-automorphisms of $L$ is not isomorphic to $S_n$.
\end{theorem}
\begin{proof}
The automorphism group of a finite-field extension is cyclic, generated by an appropriate Frobenius automorphism, and is therefore commutative. The group $S_n$ is noncommutative for $n\ge3$. An isomorphism preserves commutativity, so none can exist.
\end{proof}

Thus an asymptotic claim that finite-field Galois groups become $S_n$ is untenable in degrees at least three. Degree two conceals the issue because $S_2$ is cyclic.

\section{Frobenius and factorization type}
Let $f\in\F_q[X]$ be squarefree of degree $n$, with root set $\Omega$ in an algebraic closure. Frobenius
\[
\operatorname{Fr}_q(\alpha)=\alpha^q
\]
permutes $\Omega$. If $g$ is an irreducible factor of degree $d$, its roots form one Frobenius orbit of length $d$. Therefore, if $f=g_1\cdots g_k$ with distinct irreducible factors of degrees $d_1,\ldots,d_k$, then the Frobenius permutation has cycle lengths $d_1,\ldots,d_k$. In particular, for squarefree $f$, the number of base-field roots, the number of linear factors, and the number of Frobenius fixed points coincide.

Repeated roots must be isolated: multiplicity is not encoded by an ordinary permutation of $n$ distinct roots. Quantitative cycle-type comparisons should therefore restrict to squarefree polynomials or control the discriminant-zero locus separately.

\section{Algorithms and examples}
For prime $p$, exhaustive root-incidence enumeration traverses all $p^n$ lower-coefficient vectors and all $p$ candidate roots. Straightforward polynomial evaluation costs $O(n)$ per pair, for total time $O(np^{n+1})$ and $O(n)$ auxiliary storage. The total must equal $p^n$.

Exhaustive fixed-point enumeration traverses $n!$ permutations and tests $n$ positions, costing $O(n\,n!)$ time and $O(n)$ working storage. The total must equal $n!$.

Over $\F_2$, the four monic quadratics have four total root incidences. Over $\F_3$, the nine monic quadratics have nine incidences, and the twenty-seven monic cubics have twenty-seven. In $S_3$, the identity contributes three fixed points, the three transpositions contribute one each, and the two $3$-cycles contribute none, totaling $6$. Hence the $\F_3$, degree-$3$ bridge reads
\[
27\cdot6=6\cdot27=162.
\]

\section{Applications and limitations}
The theorem corrects the target of finite-field arithmetic experiments: factorization and Frobenius cycle types should be compared with permutation cycle types. It also supplies an exact software invariant for root-enumeration routines and an average output-size bound of one root for uniformly sampled monic polynomials.

The result proves equality only of first moments. Root counts and fixed-point counts can have different distributions, especially over small rings or rings with zero divisors. The ring-level theorem does not itself provide a Frobenius interpretation, which is field-specific. Nor does it establish a full $O_n(1/q)$ comparison of factorization types; such a result requires squarefree counts and control of every partition of $n$.

\section{Future directions}
The natural program has seven parts. First, establish the full factorization/Frobenius dictionary with explicit separability hypotheses. Second, compare ordered tuples of distinct roots and fixed points to obtain factorial moments and Poisson-type identities. Third, count squarefree monic polynomials exactly and isolate discriminant zero. Fourth, compare every factorization partition $\lambda\vdash n$ with the matching permutation cycle type and seek an $O_n(1/q)$ discrepancy. Fifth, audit degrees two and three separately, distinguishing reducibility, separability, cycle type, and abstract Galois group. Sixth, identify the Frobenius generator and connect its order to the least common multiple of cycle lengths. Seventh, formulate all finite counts directly as expectations on uniform finite probability spaces.

\section{Further structural consequences}
Let $N_k(K,n)$ be the number of monic degree-$n$ polynomials over $K$ having exactly $k$ distinct roots. The Root-Incidence Theorem is equivalent to
\[
\sum_{k=0}^{q}N_k(K,n)=q^n,
\qquad
\sum_{k=0}^{q}kN_k(K,n)=q^n.
\]
Subtracting gives an exact balance law.

\begin{corollary}[Balance of rootless and multi-rooted polynomials]
For every finite commutative ring $K$ and $n>0$,
\[
N_0(K,n)=\sum_{k=2}^{q}(k-1)N_k(K,n).
\]
Thus rootless polynomials are balanced by the excess-root mass of polynomials having at least two roots.
\end{corollary}
\begin{proof}
Partition the coefficient space by the value of $R(v)$ and subtract the total-object identity from the total-incidence identity. Terms with exactly one root cancel.
\end{proof}

If $D_k(n)$ counts permutations in $S_n$ with exactly $k$ fixed points, the identical argument gives
\[
D_0(n)=\sum_{k=2}^{n}(k-1)D_k(n).
\]
Derangements are therefore balanced by excess fixed points among permutations with at least two fixed points.

The fiber lemma also gives a direct conditional sampler.
\begin{corollary}[Rejection-free prescribed-root sampling]
Fix $r\in K$. A uniform monic degree-$n$ polynomial conditioned to vanish at $r$ is obtained by choosing $v_1,\ldots,v_{n-1}$ independently and uniformly in $K$ and setting
\[
v_0=-\left(r^n+\sum_{i=1}^{n-1}v_ir^i\right).
\]
\end{corollary}
\begin{proof}
Lemma~\ref{lem:fiber} identifies the prescribed-root fiber bijectively with $K^{n-1}$, and a bijection of finite sets preserves uniform measure.
\end{proof}

The permutation analogue fixes a prescribed letter and uniformly permutes the other $n-1$ letters. These consequences emphasize that the first moment is already exactly one at every finite size. Nontrivial asymptotic information must occur in higher moments or in individual root-count and cycle-count probabilities. Over a field, prescribing $j\le n$ distinct roots is expected to impose $j$ independent linear conditions and leave $q^{n-j}$ coefficient vectors, paralleling the $(n-j)!$ permutations that fix $j$ prescribed letters. This is the direct route to factorial-moment extensions.

\section{Conclusion}
Finite-field Galois groups do not become symmetric in degree at least three; cyclicity forbids it. The correct stochastic correspondence lies in Frobenius cycle statistics. Its first-moment instance is exact: the average number of roots of a monic polynomial over any finite commutative ring and the average number of fixed points of a permutation are both one. This replaces an impossible group identification with a precise observable bridge and provides a foundation for higher moments and full factorization-type comparisons.

\end{document}

