from itertools import product
from typing import Dict, Tuple

def value(a: Tuple[int, ...], x: int, p: int) -> int:
    y = 1
    for c in reversed(a):
        y = (y*x+c) % p
    return y

def root_distribution(p: int, n: int) -> Dict[int, int]:
    out: Dict[int, int] = {}
    for a in product(range(p), repeat=n):
        k = sum(value(a, x, p) == 0 for x in range(p))
        out[k] = out.get(k, 0) + 1
    return dict(sorted(out.items()))

if __name__ == "__main__":
    for p, n in [(2,2),(3,2),(3,3),(5,3)]:
        d=root_distribution(p,n)
        total=sum(k*v for k,v in d.items())
        print(p,n,d,total,"expected",p**n)

from itertools import permutations
from math import factorial
from typing import Dict

def fixed_distribution(n: int) -> Dict[int, int]:
    out: Dict[int, int] = {}
    for s in permutations(range(n)):
        k=sum(i==s[i] for i in range(n))
        out[k]=out.get(k,0)+1
    return dict(sorted(out.items()))

if __name__ == "__main__":
    for n in range(1,9):
        d=fixed_distribution(n)
        total=sum(k*v for k,v in d.items())
        print(n,d,total,"expected",factorial(n))

from itertools import product
from typing import List, Tuple

def value(a: Tuple[int, ...], x: int, p: int) -> int:
    y=1
    for c in reversed(a): y=(y*x+c)%p
    return y

def fibers(p: int, n: int) -> List[int]:
    vectors=list(product(range(p),repeat=n))
    return [sum(value(a,r,p)==0 for a in vectors) for r in range(p)]

if __name__ == "__main__":
    for p,n in [(2,2),(3,3),(5,4)]:
        f=fibers(p,n)
        print(p,n,f,"expected each",p**(n-1))

